example.text:
{
  settings = {
    entryPoints = {
      web = {
        address = ":80";
      };
      websecure = {
        address = ":443";
      };
    };
  };
}

{
  entryPoints = {
    web = {
      address = ":80";
      http = {
        redirections = {
          entryPoint = {
            permanent = true;
            scheme = "https";
            to = "websecure";
          };
        };
      };
    };
    websecure = {
      address = ":443";
      asDefault = true;
    };
  };
}

{
  dashboard = {
    settings = {
      http = {
        routers = {
          api = {
            rule = "Host(`198.51.100.1`)";
            service = "api@internal";
          };
        };
      };
    };
  };
}

services.traefik.routing.provider.direct.description:
Directory Traefik watches for routing configuration files.

::: {.note}
{option}`services.traefik.routing.settings` is written to `_nixos-settings.yml` and
each {option}`services.traefik.routing.extraFiles` entry to `_nixos-extra-<name>.yml`;
you may add your own files too.
:::
